def read_current_episode_binding_v1(repo, controller, expected_current=None):
    """Read the canonical OPEN binding, including through verified terminal lineage.

    This read-only owner entry never accepts an actual child UUID, profile,
    packet, logical task, host generation or receipt from its caller.
    """
    with current_route_observation_v1(repo, controller, expected_current) as observed:
        value = observed.opening_bytes()
    return decoded_artifact(value, 'current episode binding')


def read_current_ordinary_result_v1(repo, controller):
    """Read an ordinary audit-assess return/acceptance from canonical custody.

    Native child UUIDs and host execution are deliberately not inferred here.
    The selected source owner independently authenticates those public records.
    """
    with current_route_observation_v1(repo, controller) as observed:
        result = observed.ordinary_result_bytes()
    return decoded_artifact(result, 'current ordinary result projection')


def read_applicable_ordinary_result_v1(repo, controller):
    """Skip unrelated roles only to an unavailable, non-authoritative floor.

    This is not a cheap currentness proof. Applicable ordinary reviews still use
    the complete live reader. The negative result contains no route facts and
    cannot establish absence of an obligation or permit an effect.
    """
    source = file_digest(Path(__file__).resolve())
    oid, record = current_ref(repo, controller)
    if oid is None or record is None:
        return read_current_ordinary_result_v1(repo, controller)
    applicable = (record['decision'] == 'REQUIRED'
                  and mapped_child_route(record)[0] == 'audit-assess')
    if applicable:
        return read_current_ordinary_result_v1(repo, controller)
    validate_canonical_route_record_bytes(repo, oid, record)
    if (current_ref(repo, controller) != (oid, record)
            or file_digest(Path(__file__).resolve()) != source):
        fail('ordinary applicability input changed during observation')
    return {'status': 'CANONICAL_REVIEW_ABSENT', 'canonical_route': None}


def _ordinary_result_from_read_v1(repo, oid, record, current):
    """Private projection of one source-owned, provisional canonical tuple."""
    if record['decision'] != 'REQUIRED':
        return {'status': 'CANONICAL_REVIEW_ABSENT', 'canonical_route': current}
    role, _ = mapped_child_route(record)
    if role != 'audit-assess':
        return {'status': 'CANONICAL_REVIEW_ABSENT', 'canonical_route': current}
    if record['route_state'] == 'UNSATISFIED':
        return {'status': 'CANONICAL_REVIEW_ABSENT', 'canonical_route': current}
    opening = _episode_from_read_v1(repo, oid, record, current)
    scope = _scope_from_read_v1(record, current)
    life = record['lifecycle']
    packet_wire = life['delivery']['packet']
    packet = decoded_artifact(validate_bytes_identity(packet_wire, 'ordinary packet'), 'ordinary packet')
    route_packet_record(packet, record['obligation_id'], record['route_transaction_id'], expected_target='audit-assess')
    returned_wire = life['child_return']
    decision_wire = life['governor_decision']
    if returned_wire is not None:
        returned = decoded_artifact(validate_bytes_identity(returned_wire, 'ordinary return'), 'ordinary return')
        child_return_record(returned, record['obligation_id'], record['route_transaction_id'],
                            packet_wire['digest'], expected_child='audit-assess')
    if decision_wire is not None:
        if returned_wire is None or life['governor_decision_count'] != 1:
            fail('ordinary acceptance lacks one exact return')
        decision = decoded_artifact(validate_bytes_identity(decision_wire, 'ordinary acceptance'), 'ordinary acceptance')
        governor_decision_record(decision, record['obligation_id'], record['route_transaction_id'], returned_wire['digest'])
    expected = {'OPEN': (False, False), 'RETURNED': (True, False), 'SATISFIED': (True, True)}
    if expected.get(record['route_state']) != (returned_wire is not None, decision_wire is not None):
        fail('ordinary lifecycle members contradict canonical state')
    return {'status': record['route_state'], 'canonical_route': current,
            'opening': opening, 'scope': scope['scope'], 'packet': packet_wire,
            'child_return': returned_wire, 'governor_decision': decision_wire}


def _scope_from_read_v1(record, route):
    """Pure scope formatting; standalone public reader keeps its old fences."""
    request = candidate_request_from_record(record, require_current_inputs=True)
    scope = dict(request['scope'])
    if scope['digest'] != digest_json({'identity': scope['identity']}):
        fail('route scope digest is contradictory')
    record_raw = json.dumps(record, sort_keys=True, separators=(',', ':'), ensure_ascii=True,
                            allow_nan=False).encode('utf-8') + b'\n'
    value = {'schema': 'implementaudit.current-route-scope.v1', 'authority_ceiling': 'READ_ONLY_CURRENT_ROUTE_FACT',
        'establishes': [], 'route': dict(route), 'scope': scope, 'boundary': dict(request['boundary']),
        'owner': {key: record[key] for key in ('controller_id', 'claim_id', 'explicit_run_root', 'continuity_generation', 'continuity_receipt')},
        'host': {key: record[key] for key in ('host_id', 'host_session_id', 'host_binding_generation', 'host_correlation_id')},
        'source': {'predicate_version': record['predicate_version'], 'record_schema': record['schema'],
                   'producer_sha256': file_digest(Path(__file__).resolve())[7:], 'record_sha256': hashlib.sha256(record_raw).hexdigest()},
        'expiry_fingerprint': record['expiry_fingerprint'],
        'satisfaction': record['lifecycle']['governor_decision']['digest'] if route['route_state'] == 'SATISFIED' else None}
    value['digest'] = digest_json(value)[7:]
    return value


def _episode_from_read_v1(repo, oid, record, route):
    """Validate immutable OPEN lineage once inside the enclosing read fence."""
    if record.get('route_state') not in {'OPEN', 'RETURNED', 'SATISFIED'}:
        fail('canonical episode has no OPEN lineage', decision='REQUIRED')
    with RouteObjectReader(repo) as object_reader:
        validate_lifecycle_predecessor_chain(repo, oid, record, object_reader=object_reader)
        opened, opened_oid = record, oid
        for _ in range(3):
            if opened.get('route_state') == 'OPEN':
                break
            predecessor = opened.get('predecessor_record_oid')
            if not isinstance(predecessor, str) or not OID_RE.fullmatch(predecessor):
                fail('canonical episode predecessor is malformed')
            opened = decoded_artifact(git_blob_bytes(repo, predecessor, 'canonical episode OPEN predecessor',
                object_reader=object_reader), 'canonical episode OPEN predecessor')
            validate_canonical_route_record_bytes(repo, predecessor, opened, object_reader=object_reader)
            opened_oid = predecessor
        else:
            fail('canonical episode exceeds OPEN/RETURNED/SATISFIED lineage')
        logical_task = open_logical_task(opened)
        role, target = mapped_child_route(opened)
        delivery = opened['lifecycle']['delivery']
        validate_bytes_identity(delivery['packet'], 'canonical OPEN packet')
        validate_bytes_identity(delivery['child'], 'canonical OPEN skill', with_identity=True)
    keys = ('host_id', 'host_session_id', 'host_binding_generation', 'host_correlation_id',
            'continuity_generation', 'continuity_receipt', 'obligation_id', 'route_transaction_id',
            'controller_id', 'claim_id', 'explicit_run_root')
    if any(record.get(key) != opened.get(key) for key in keys):
        fail('canonical OPEN identity changed across retained lineage')
    value = {'schema': 'implementaudit.r0033-current-episode-binding.v1', 'route_current': route,
        'open_record_oid': opened_oid, 'open_record_identity': opened['record_identity'], 'logical_task': logical_task,
        'selected_child_role': role, 'selected_child_target': target,
        'packet_pin': {key: delivery['packet'][key] for key in ('bytes', 'digest')},
        'skill_pin': {key: delivery['child'][key] for key in ('identity', 'bytes', 'digest')},
        'host_and_scope': {key: opened[key] for key in keys},
        'canonical_route_currentness': 'VALIDATED_AT_READ', 'authority_ceiling': 'NONE'}
    opening = {key: value[key] for key in ('open_record_oid', 'open_record_identity', 'logical_task',
        'selected_child_role', 'selected_child_target', 'packet_pin', 'skill_pin', 'host_and_scope')}
    return {**value, 'opening_digest': digest_json(opening), 'binding_digest': digest_json(value)}


_ROUTE_READ_ISSUER_V1 = object()


class _CurrentRouteReadV1:
    """Owner-issued provisional projections, unusable for new reads after exit.

    This is not a serializable credential or a cache. Every public entry creates
    a new view from live owner predicates; every successful exit rederives them.
    """
    __slots__ = ('__repo', '__oid', '__record', '__route', '__initial', '__active', '__execution')

    def __init__(self, issuer, repo, oid, record, route):
        if issuer is not _ROUTE_READ_ISSUER_V1:
            fail('current route view must be acquired by its source owner')
        self.__repo, self.__oid = repo, oid
        self.__record, self.__route = copy.deepcopy(record), copy.deepcopy(route)
        self.__initial = digest_json([self.__record, self.__route])
        self.__active = True
        self.__execution = None

    def __emit(self, value):
        self.__check()
        # Canonical bytes cannot be mutated and restored between fence reads.
        # The fixed consumer decodes its own copy; no yielded dict is trusted.
        return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False,
                          allow_nan=False).encode('utf-8')

    def __check(self):
        if not self.__active:
            fail('current route observation is closed')
        if digest_json([self.__record, self.__route]) != self.__initial:
            fail('provisional current route data was mutated')

    def scope_bytes(self):
        self.__check()
        return self.__emit(_scope_from_read_v1(self.__record, self.__route))

    def opening_bytes(self):
        self.__check()
        return self.__emit(_episode_from_read_v1(self.__repo, self.__oid, self.__record, self.__route))

    def ordinary_result_bytes(self):
        self.__check()
        return self.__emit(_ordinary_result_from_read_v1(self.__repo, self.__oid, self.__record, self.__route))

    def ordinary_receiver_binding_bytes(self):
        self.__check()
        return self.__emit(_ordinary_receiver_binding_from_read_v1(self.__repo, self.__record, self.__route))

    def ordinary_execution_bytes(self):
        self.__check()
        canonical = _ordinary_result_from_read_v1(self.__repo, self.__oid, self.__record, self.__route)
        value = self.__emit(_ordinary_execution_from_read_v1(self.__repo, self.__route['controller_id'], canonical))
        if self.__execution is not None and value != self.__execution:
            fail('ordinary receiver accepted custody changed during observation')
        self.__execution = value
        return value

    def _check_owner_exit(self, issuer):
        if issuer is not _ROUTE_READ_ISSUER_V1:
            fail('foreign current route exit')
        self.__check()
        if self.__execution is not None:
            self.ordinary_execution_bytes()

    def _close_owner_read(self, issuer):
        if issuer is not _ROUTE_READ_ISSUER_V1:
            fail('foreign current route close')
        self.__active = False


@contextlib.contextmanager
def current_route_observation_v1(repo, controller, expected_current=None):
    """Acquire a bounded owner read; yielded facts are provisional until exit.

    Accepts no supplied record, callback, module, trusted flag or reusable token.
    A successful exit performs the complete fresh semantic/currentness check,
    including request inputs, package and child source, not merely ref equality.
    """
    expected = copy.deepcopy(expected_current)
    source = file_digest(Path(__file__).resolve())
    opening = _open_pure_route_read_v1(repo, controller, expected)
    def closing():
        return current_controller(repo, controller, environment=opening[0])
    with _route_observation_lifetime_v1(repo, controller, expected, source, opening, closing) as view:
        yield view


@contextlib.contextmanager
def _route_observation_lifetime_v1(repo, controller, expected, source, opening, _closing_current):
    # Private composition. Public entries alone acquire currentness; the fixed
    # source-owned closing continuation runs after semantics and before final refs.
    environment, current, oid, record, route = opening
    final_oid, final_record = current_ref(repo, controller)
    if (final_oid, final_record) != (oid, record):
        fail('canonical route changed before combined observation')
    if oid != route['record_oid'] or record is None or any(record.get(key) != route[key] for key in (
            'controller_id', 'record_identity', 'decision', 'classification', 'route_transaction_id', 'obligation_id', 'route_state')):
        fail('canonical route changed before combined observation')
    validate_canonical_route_record_bytes(repo, oid, record)
    record = copy.deepcopy(record)
    view = _CurrentRouteReadV1(_ROUTE_READ_ISSUER_V1, repo, oid, record, route)
    try:
        yield view
        view._check_owner_exit(_ROUTE_READ_ISSUER_V1)
        if current_ref(repo, controller) != (oid, record):
            fail('canonical route changed during combined observation')
        validate_canonical_route_record_bytes(repo, oid, record)
        if _pure_route_semantics_v1(repo, controller, oid, record, current, expected) != route:
            fail('canonical route semantics changed during combined observation')
        if _closing_current() != current:
            fail('current controller changed during combined observation')
        _pure_route_final_ref_fence(repo, controller, route['controller_record_oid'], oid)
        if file_digest(Path(__file__).resolve()) != source:
            fail('route source changed during combined observation')
        view._check_owner_exit(_ROUTE_READ_ISSUER_V1)
    finally:
        view._close_owner_read(_ROUTE_READ_ISSUER_V1)


@contextlib.contextmanager
def _observe_current_route_from_owner_v1(repo, controller, owner_read, expected_current, closing_current):
    """Private graph-owner composition, not a public supplied-proof entry."""
    expected = copy.deepcopy(expected_current)
    source = file_digest(Path(__file__).resolve())
    exact_keys(owner_read, {'controller_result', 'receipt'}, 'actual continuity owner read')
    current = _current_controller_from_owner_read_v1(repo, controller, owner_read['controller_result'], owner_read['receipt'])
    oid, record = current_ref(repo, controller)
    if oid is None or record is None:
        fail('canonical route decision is absent')
    validate_canonical_route_record_bytes(repo, oid, record)
    route = _pure_route_semantics_v1(repo, controller, oid, record, current, expected)
    _pure_route_final_ref_fence(repo, controller, current['controller_record_oid'], oid)
    with _route_observation_lifetime_v1(repo, controller, expected, source,
            (None, current, oid, record, route), closing_current) as view:
        yield view


def _ordinary_execution_ref_v1(controller, canonical):
    opening = canonical['opening']['opening_digest']
    if canonical['status'] != 'SATISFIED' or not HEX_RE.fullmatch(opening):
        fail('ordinary receiver requires current exact parent acceptance')
    return 'refs/implementaudit/ordinary-receivers/' + controller + '/' + opening.removeprefix('sha256:')


def _ordinary_execution_record_v1(value, canonical):
    exact_keys(value, {'schema', 'accepted_record_oid', 'opening_digest', 'attempt_oid', 'execution', 'execution_digest'}, 'ordinary execution record')
    if (value['schema'] != 'implementaudit.ordinary-receiver-record.v2' or
            value['accepted_record_oid'] != canonical['canonical_route']['record_oid'] or
            value['opening_digest'] != canonical['opening']['opening_digest'] or
            not isinstance(value['attempt_oid'], str) or not OID_RE.fullmatch(value['attempt_oid']) or
            value['execution_digest'] != digest_json(value['execution'])):
        fail('ordinary receiver execution has foreign accepted custody')
    execution = value['execution']
    exact_keys(execution, {'schema', 'policy_digest', 'opening_digest', 'return_digest', 'acceptance_digest',
        'argv', 'python_pin', 'source_pin', 'exit_code', 'stdout', 'stdout_sha256', 'stderr_sha256'}, 'ordinary execution')
    if (execution['schema'] != 'implementaudit.ordinary-receiver-execution.v1' or
            execution['opening_digest'] != value['opening_digest'] or
            execution['return_digest'] != canonical['child_return']['digest'] or
            execution['acceptance_digest'] != canonical['governor_decision']['digest'] or
            type(execution['exit_code']) is not int or type(execution['stdout']) is not str or
            len(execution['stdout'].encode('utf-8')) > 256 * 1024 or
            execution['stdout_sha256'] != hashlib.sha256(execution['stdout'].encode('utf-8')).hexdigest()):
        fail('ordinary receiver execution result is malformed or foreign')
    return value


def _ordinary_attempt_v2(canonical, policy_digest):
    return {'schema': 'implementaudit.ordinary-receiver-attempt.v1',
        'accepted_record_oid': canonical['canonical_route']['record_oid'],
        'opening_digest': canonical['opening']['opening_digest'], 'policy_digest': policy_digest,
        'return_digest': canonical['child_return']['digest'], 'acceptance_digest': canonical['governor_decision']['digest']}


def _ordinary_publish_v2(repo, controller, canonical, ref, raw, *, verify_refs=()):
    oid = write_route_record_blob(repo, raw.decode('utf-8'))
    route = canonical['canonical_route']
    transaction = ('start\nverify ' + route['ref'] + ' ' + route['record_oid'] + '\nverify refs/implementaudit/controllers/' +
        controller + ' ' + route['controller_record_oid'] + '\n' +
        ''.join('verify ' + name + ' ' + expected + '\n' for name, expected in verify_refs) +
        'update ' + ref + ' ' + oid + ' ' + ZERO_OID + '\nprepare\ncommit\n')
    completed = subprocess.run([str(trusted_host_executable(repo, 'git')), '-c', 'core.hooksPath=' + os.devnull,
        'update-ref', '--stdin'], cwd=repo, env=sanitized_action_environment(), input=transaction.encode('ascii'),
        capture_output=True, check=False)
    if completed.returncode or git(repo, 'rev-parse', '--verify', ref) != oid:
        fail('ordinary receiver expected-absence publication refused; reconcile effect before retry')
    return oid


def read_current_ordinary_execution_v1(repo, controller):
    """Resolve only the current canonical accepted opening's immutable receipt."""
    canonical = read_current_ordinary_result_v1(repo, controller)
    value = _ordinary_execution_from_read_v1(repo, controller, canonical)
    if value is not None and (read_current_ordinary_result_v1(repo, controller) != canonical or
            git(repo, 'rev-parse', '--verify', value['ref']) != value['oid']):
        fail('ordinary receiver accepted custody changed during read')
    return value


def _ordinary_execution_from_read_v1(repo, controller, canonical):
    """Private receipt projection inside the source owner's active route read."""
    ref = _ordinary_execution_ref_v1(controller, canonical)
    rows = git(repo, 'for-each-ref', '--format=%(objectname) %(refname)', ref).splitlines()
    if not rows:
        return None
    if len(rows) != 1 or rows[0].split(' ', 1)[-1] != ref:
        fail('ordinary receiver ref namespace is ambiguous')
    oid = rows[0].split(' ', 1)[0]
    raw = git_blob_bytes(repo, oid, 'ordinary receiver execution')
    record = _ordinary_execution_record_v1(decoded_artifact(raw, 'ordinary receiver execution'), canonical)
    attempt_ref = ref.replace('/ordinary-receivers/', '/ordinary-receiver-attempts/')
    if git(repo, 'rev-parse', '--verify', attempt_ref) != record['attempt_oid']:
        fail('ordinary receiver attempt custody differs')
    attempt = decoded_artifact(git_blob_bytes(repo, record['attempt_oid'], 'ordinary receiver attempt'), 'ordinary receiver attempt')
    if attempt != _ordinary_attempt_v2(canonical, record['execution']['policy_digest']):
        fail('ordinary receiver attempt binding differs')
    if (git(repo, 'rev-parse', '--verify', ref) != oid or
            git(repo, 'rev-parse', '--verify', attempt_ref) != record['attempt_oid']):
        fail('ordinary receiver accepted custody changed during read')
    return {'ref': ref, 'oid': oid, 'wire': bytes_identity(raw)}


def record_current_ordinary_execution_v1(repo, controller, execution):
    """Retired unsafe observation operand; it cannot publish process credit."""
    fail('caller-supplied ordinary execution results are not accepted')


@contextlib.contextmanager
def _ordinary_fixed_source_owner_v2(repo, code_pins):
    """Hold the two fixed, exact Git-backed bootstrap sources; execute no task."""
    import types
    if os.name != 'nt':
        fail('ordinary receiver bootstrap requires Windows held-file custody')

    def bound_blob(name):
        relative = 'skills/implementaudit/scripts/' + name
        expected = code_pins.get('implementaudit/scripts/' + name)
        if not isinstance(expected, str) or re.fullmatch('[0-9a-f]{64}', expected) is None:
            fail('ordinary receiver source pin is missing')
        oid = git(repo, 'rev-parse', '--verify', 'HEAD:' + relative)
        size = git(repo, 'cat-file', '-s', oid)
        if re.fullmatch('[0-9]+', size) is None or not 0 < int(size) <= 65536:
            fail('ordinary receiver source exceeds its pre-read bound')
        raw = git_blob_bytes(repo, oid, 'ordinary receiver source')
        if not 0 < len(raw) <= 65536 or hashlib.sha256(raw).hexdigest() != expected:
            fail('ordinary receiver source differs from accepted policy')
        return Path(repo) / relative, raw

    custody_path, custody_raw = bound_blob('bounded_file_custody.py')
    custody = types.ModuleType('_ordinary_receipt_custody'); custody.__file__ = str(custody_path)
    exec(compile(custody_raw, str(custody_path), 'exec', dont_inherit=True), custody.__dict__)
    owner_path, owner_raw = bound_blob('compaction-source-owner-codex-app.py')
    with custody.held_file(custody_path, allow_append=False) as custody_stream, \
            custody.held_file(owner_path, allow_append=False) as owner_stream:
        for stream, raw in ((custody_stream, custody_raw), (owner_stream, owner_raw)):
            info = os.fstat(stream.fileno())
            if info.st_nlink != 1 or info.st_size != len(raw) or stream.read(len(raw) + 1) != raw:
                fail('ordinary receiver active source differs from its bound blob')
        owner = types.ModuleType('_ordinary_receipt_source'); owner.__file__ = str(owner_path)
        exec(compile(owner_raw, str(owner_path), 'exec', dont_inherit=True), owner.__dict__)
        yield owner


def _ordinary_receiver_binding_from_read_v1(repo, record, route):
    """Read-only availability of the sole fixed executor, never effect credit.

    Source pins come from current canonical request inputs, not a caller flag
    or module. The enclosing owner observation revalidates them on exit.
    """
    if (record['decision'] != 'REQUIRED' or record['route_state'] != 'SATISFIED'
            or mapped_child_route(record)[0] != 'audit-assess'):
        return None
    packet = decoded_artifact(validate_bytes_identity(record['lifecycle']['delivery']['packet'], 'ordinary packet'), 'ordinary packet')
    try:
        mission = json.loads(packet['source_event']['body'], object_pairs_hook=unique_object)
    except (ValueError, TypeError):
        return None
    if type(mission) is not dict or mission.get('schema') != 'implementaudit.ordinary-review-mission.v1':
        return None
    exact_keys(mission, {'schema', 'policy_digest', 'scope', 'mission', 'authority_ceiling'}, 'ordinary mission')
    request = candidate_request_from_record(record, require_current_inputs=True)
    inputs = {item['path']: item['digest'] for item in request['inputs']}
    names = ('bounded_file_custody.py', 'compaction-source-owner-codex-app.py')
    if any('skills/implementaudit/scripts/' + name not in inputs for name in names):
        return None
    pins = {'implementaudit/scripts/' + name: inputs['skills/implementaudit/scripts/' + name].removeprefix('sha256:') for name in names}
    with _ordinary_fixed_source_owner_v2(repo, pins) as owner:
        policy = owner.ordinary_policy_v1()
        if (type(policy) is not dict or policy.get('schema') != 'implementaudit.ordinary-native-policy.v1'
                or digest_json(policy).removeprefix('sha256:') != mission['policy_digest']
                or mission['scope'] != request['scope'] or mission['authority_ceiling'] != 'NONE'
                or any(policy.get('code_pins', {}).get(key) != value for key, value in pins.items())
                or policy.get('code_pins', {}).get('implementaudit/scripts/route-transaction.py') != file_digest(Path(__file__).resolve())[7:]
                or policy.get('receiver_argv') != [policy.get('provider', {}).get('python_executable', {}).get('path'),
                    '-I', '-S', '-B', str(Path(repo) / 'skills/implementaudit/scripts/compaction-source-owner-codex-app.py'), '--ordinary-receiver']):
            fail('ordinary receiver binding differs from accepted fixed policy')
        for key in ('receiver_node', 'consumer'):
            if type(policy.get(key)) is not str or not policy[key]:
                fail('ordinary receiver binding has no exact consumer')
        if owner.ordinary_policy_v1() != policy:
            fail('ordinary receiver binding policy changed during read')
    raw = json.dumps(record, sort_keys=True, separators=(',', ':'), ensure_ascii=True, allow_nan=False).encode('utf-8') + b'\n'
    return {'schema': 'implementaudit.ordinary-receiver-binding.v1', 'producer': 'R0033',
        'executor': 'execute_current_ordinary_receiver_v2', 'route_record_oid': route['record_oid'],
        'route_scope_digest': _scope_from_read_v1(record, route)['digest'], 'policy': policy,
        'record': bytes_identity(raw), 'source_pins': pins, 'authority_ceiling': 'NONE', 'establishes': []}


def execute_current_ordinary_receiver_v2(repo, controller, policy):
    """Run and capture the bound receiver under the receipt publication lease.

    Policy is immutable prospective input bound by the accepted packet. There
    is no caller process-result, command, callback or module operand. Bootstrap
    source comes from exact policy-bound Git blobs, then held worktree bytes.
    """
    # Freeze caller-owned nested containers before any other owner call. The
    # digest check and every later bootstrap/effect read use this same value.
    if type(policy) is not dict:
        fail('ordinary receiver policy is not the accepted prospective policy')
    try:
        policy_raw = json.dumps(policy, sort_keys=True, separators=(',', ':'),
            ensure_ascii=False, allow_nan=False).encode('utf-8')
        if len(policy_raw) > MAX_ROUTE_RECORD_BYTES:
            fail('ordinary receiver policy exceeds its bound')
        policy = json.loads(policy_raw, object_pairs_hook=unique_object)
    except (TypeError, ValueError, UnicodeError, RecursionError):
        fail('ordinary receiver policy is not bounded canonical JSON')
    common = str(Path(git(repo, 'rev-parse', '--path-format=absolute', '--git-common-dir')).resolve())
    with namespace_gate(common):
        canonical = read_current_ordinary_result_v1(repo, controller)
        ref = _ordinary_execution_ref_v1(controller, canonical)
        packet = decoded_artifact(validate_bytes_identity(canonical['packet'], 'ordinary packet'), 'ordinary packet')
        mission = json.loads(packet['source_event']['body'], object_pairs_hook=unique_object)
        if (type(policy) is not dict or policy.get('schema') != 'implementaudit.ordinary-native-policy.v1'
                or mission.get('schema') != 'implementaudit.ordinary-review-mission.v1'
                or mission.get('policy_digest') != hashlib.sha256(policy_raw).hexdigest()
                or mission.get('scope') != canonical['scope'] or mission.get('authority_ceiling') != 'NONE'):
            fail('ordinary receiver policy is not the accepted prospective policy')
        source_path = Path(repo) / 'skills/implementaudit/scripts/compaction-source-owner-codex-app.py'
        if policy.get('receiver_argv') != [policy.get('provider', {}).get('python_executable', {}).get('path'),
                '-I', '-S', '-B', str(source_path), '--ordinary-receiver']:
            fail('ordinary receiver command differs from the fixed owner entry')
        existing = read_current_ordinary_execution_v1(repo, controller)
        if existing is not None:
            return {'status': 'EXISTING_EXECUTION_PRESERVED', 'receipt': existing, 'executed': False}
        attempt_ref = ref.replace('/ordinary-receivers/', '/ordinary-receiver-attempts/')
        if git(repo, 'for-each-ref', '--format=%(refname)', attempt_ref):
            fail('ordinary receiver prior attempt has no completed receipt; reconcile, do not replay')

        with _ordinary_fixed_source_owner_v2(repo, policy.get('code_pins', {})) as owner:
            if owner.ordinary_policy_v1() != policy:
                fail('ordinary receiver active policy changed')
            attempt_raw = json.dumps(_ordinary_attempt_v2(canonical, mission['policy_digest']), sort_keys=True,
                separators=(',', ':'), ensure_ascii=True, allow_nan=False).encode('utf-8') + b'\n'
            attempt_oid = _ordinary_publish_v2(repo, controller, canonical, attempt_ref, attempt_raw)
            # The fixed source executes and captures the process here, while
            # this same lease still excludes concurrent check/run/publication.
            execution = owner._ordinary_receiver_observation_v2()
            if owner.ordinary_policy_v1() != policy or read_current_ordinary_result_v1(repo, controller) != canonical:
                fail('ordinary receiver effect observed but inputs changed; reconcile before retry')
        value = {'schema': 'implementaudit.ordinary-receiver-record.v2',
            'accepted_record_oid': canonical['canonical_route']['record_oid'],
            'opening_digest': canonical['opening']['opening_digest'],
            'attempt_oid': attempt_oid,
            'execution': execution, 'execution_digest': digest_json(execution)}
        _ordinary_execution_record_v1(value, canonical)
        raw = json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True, allow_nan=False).encode('utf-8') + b'\n'
        oid = _ordinary_publish_v2(repo, controller, canonical, ref, raw, verify_refs=((attempt_ref, attempt_oid),))
        if read_current_ordinary_result_v1(repo, controller) != canonical:
            fail('ordinary receiver receipt retained but currentness changed; no current credit')
        result = read_current_ordinary_execution_v1(repo, controller)
        if result != {'ref': ref, 'oid': oid, 'wire': bytes_identity(raw)}:
            fail('ordinary receiver execution receipt readback differs')
        return {'status': 'EXECUTION_RECORDED', 'receipt': result, 'executed': True}

