def recovery_request_v3(capsule: dict[str, Any]) -> dict[str, Any]:
    argv = ["route-trigger", "STALE_CONTEXT_RECONSTRUCTION"]
    return {"schema": REQUEST_SCHEMA, "predicate_version": PREDICATE_VERSION,
